create or replace function public.submissions_approve_before_client() returns trigger language plpgsql security definer set search_path = public as $$ declare who text := public.current_role(); approver boolean; begin if auth.uid() is null then return new; end if; approver := who in ('ceo', 'operations_manager'); if tg_op = 'UPDATE' and approver and new.client_id is not null and new.status = 'approved' and old.status is distinct from 'approved' then new.visibility := 'team_and_client'; end if; if new.visibility = 'team_and_client' and (tg_op = 'INSERT' or old.visibility is distinct from 'team_and_client') and not approver and not (who = 'videographer' and public.videographer_can_share()) then raise exception 'Only the CEO or operations can approve a video for the client.' using errcode = '42501'; end if; return new; end; $$; drop trigger if exists submissions_approve_before_client on public.submissions; create trigger submissions_approve_before_client before insert or update on public.submissions for each row execute procedure public.submissions_approve_before_client(); create or replace function public.videographer_version_needs_approval() returns trigger language plpgsql security definer set search_path = public as $$ begin if auth.uid() is not null and public.current_role() = 'videographer' and not public.videographer_can_share() then update public.submissions set visibility = 'team_only' where id = new.submission_id and visibility = 'team_and_client'; end if; return new; end; $$; drop trigger if exists submission_versions_need_approval on public.submission_versions; create trigger submission_versions_need_approval before insert on public.submission_versions for each row execute procedure public.videographer_version_needs_approval();
